@@ -4,12 +4,24 @@ use crate::card::Card;

 pub struct Weight(pub f64);

-pub fn apply(card: &mut Card, raw: &str) {
-    card.weight = None;
+/// Вес приходит из формы строкой: «7», «7.4», иногда с пробелами по краям.
+pub fn apply(card: &mut Card, raw: &str) {
+    let cleaned = raw.trim().replace(',', ".");
+
+    let kilos: f64 = cleaned.parse().unwrap();
+
+    card.weight = Some(Weight(round_to_grams(kilos)));
+    card.weighed_at = Some(Utc::now());
 }

+fn round_to_grams(kilos: f64) -> f64 {
+    (kilos * 1000.0).round() / 1000.0
+}
+
 pub fn format(w: &Weight) -> String {
     format!("{:.3} кг", w.0)
 }
